function program(id){return state.programs.find(p=>p.id===id)||state.programs[0];}
function currentInstances(){return state.current?.instances||[];}
function snapshot(){return{current:clone(state.current),site:clone(state.site),sources:state.sources.map(s=>({...s,ports:clone(s.ports),pivot:clone(s.pivot)})),programs:clone(state.programs)};}
function remember(){history.push(snapshot());if(history.length>35)history.shift();future=[];}
function restoreSnapshot(s){state.current=s.current;state.site=s.site;state.sources=s.sources;state.programs=s.programs;selected=null;syncInputs();renderSources();renderProgram();buildSite();updateDesign(true);}
function undo(){if(!history.length)return toast('Nothing to undo yet.');future.push(snapshot());restoreSnapshot(history.pop());}
function redo(){if(!future.length)return toast('Nothing to redo.');history.push(snapshot());restoreSnapshot(future.pop());}
function changed(){dirty=true;clearTimeout(savingTimer);savingTimer=setTimeout(()=>{try{const data=projectData(false);if(JSON.stringify(data).length<3500000)localStorage.setItem('pace-futures-session',JSON.stringify(data));}catch{}},900);}
function optionsPrograms(id){return state.programs.map(p=>`<option value="${p.id}"${p.id===id?' selected':''}>${esc(p.short)}</option>`).join('');}
