function clearGroup(group){while(group.children.length){const obj=group.children[0];group.remove(obj);obj.traverse(o=>{if(o.geometry&&!o.userData.shared)o.geometry.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose();}});}}
