function readGizmo(){if(!selectedGroup)return;const i=currentInstances().find(i=>i.id===selected),s=i&&instanceSource(i,state.sources);if(!i||i.locked)return;const e=new T.Euler().setFromQuaternion(selectedGroup.quaternion,'YXZ');i.rotation=[e.x/DEG,e.y/DEG,e.z/DEG];i.scale=selectedGroup.scale.toArray().map(n=>Math.max(.05,n));i.position=selectedGroup.position.clone().sub(V(...s.pivot).multiply(V(...i.scale)).applyQuaternion(selectedGroup.quaternion)).toArray();}
